// Serves the FULL interview prep doc — but ONLY to a request with a valid
// password cookie (lib/auth + api/gate). The doc holds SENSITIVE prep (salary
// strategy, relocation reasons, experience framing), so this FAILS CLOSED.
//
// The HTML below is AES-256-CBC ciphertext. It is SAFE to be public (even on a
// public GitHub repo): it is useless without the COPILOT_KEY env var (64 hex
// chars) which lives ONLY in Vercel and is never committed.
const auth = require('../lib/auth');
const crypto = require('crypto');

// Persistent store for ONLINE edits (Upstash Redis via REST — same env vars as
// api/session.js: KV_REST_API_URL / KV_REST_API_TOKEN, or the UPSTASH_* names).
// If unset, online "Save" degrades to per-browser localStorage on the client and
// this file simply serves the baked-in (published) ciphertext below.
const STORE_URL = process.env.KV_REST_API_URL || process.env.UPSTASH_REDIS_REST_URL || '';
const STORE_TOK = process.env.KV_REST_API_TOKEN || process.env.UPSTASH_REDIS_REST_TOKEN || '';
const STORE_KEY = 'cp:doc:autodesk';
function storeOn() { return !!(STORE_URL && STORE_TOK); }
async function pipe(commands) {
  const r = await fetch(STORE_URL.replace(/\/$/, '') + '/pipeline', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + STORE_TOK, 'Content-Type': 'application/json' },
    body: JSON.stringify(commands)
  });
  return r.json();
}

// Publish time (epoch ms) — bumped by the re-encrypt script on every publish.
// A stored online edit only wins if it is NEWER than this, so a fresh publish
// from the repo automatically supersedes an older online edit (no manual reset).
const DOC_BUILD = 1782675696171;

const ENC_IV = "w0i7S9gJr74SmcNJRzJFUA==";
const ENC_DATA = "";

function keyCandidates() {
  const out = [];
  const seen = new Set();
  function add(buf) {
    const hex = buf.toString('hex');
    if (!seen.has(hex)) { seen.add(hex); out.push(buf); }
  }
  const rawKey = (process.env.COPILOT_KEY || '').trim();
  if (/^[0-9a-fA-F]{64}$/.test(rawKey)) add(Buffer.from(rawKey, 'hex'));
  if (rawKey) add(crypto.createHash('sha256').update(rawKey, 'utf8').digest());
  const rawPass = (process.env.COPILOT_PASS || '').trim();
  if (rawPass) add(crypto.createHash('sha256').update(rawPass, 'utf8').digest());
  return out;
}

function decryptWith(ivB64, dataB64) {
  const iv = Buffer.from(ivB64, 'base64');
  const data = Buffer.from(dataB64, 'base64');
  for (const key of keyCandidates()) {
    try {
      const dec = crypto.createDecipheriv('aes-256-cbc', key, iv);
      return Buffer.concat([dec.update(data), dec.final()]).toString('utf8');
    } catch (e) {}
  }
  return null;
}
function decryptDoc() { return decryptWith(ENC_IV, ENC_DATA); }

// Encrypt an edited doc the same way (random IV) so what we persist online is
// also AES-256-CBC ciphertext — never plaintext at rest, even in the store.
function encryptDoc(html) {
  const key = keyCandidates()[0];
  if (!key) return null;
  const iv = crypto.randomBytes(16);
  const c = crypto.createCipheriv('aes-256-cbc', key, iv);
  const data = Buffer.concat([c.update(Buffer.from(String(html), 'utf8')), c.final()]);
  return { iv: iv.toString('base64'), data: data.toString('base64') };
}

// Read the stored online edit (if any). Returns { html, savedAt } or null.
async function loadOverride() {
  if (!storeOn()) return null;
  try {
    const out = await pipe([['GET', STORE_KEY]]);
    const raw = out && out[0] && out[0].result;
    if (!raw) return null;
    const o = JSON.parse(raw);
    if (!o || !o.iv || !o.data) return null;
    const html = decryptWith(o.iv, o.data);
    if (html == null) return null;
    return { html: html, savedAt: o.savedAt || 0 };
  } catch (e) { return null; }
}

// Stamp the served HTML with the effective publish/save time so the client can
// reconcile a per-browser localStorage draft (used only when no store is set).
function injectBuilt(html, ts) {
  const tag = '<meta name="doc-built" content="' + ts + '">';
  if (/<meta name="doc-built"[^>]*>/i.test(html)) {
    return html.replace(/<meta name="doc-built"[^>]*>/i, tag);
  }
  return html.replace(/<head>/i, '<head>\n' + tag);
}

// Self-contained client script for the bilingual language-order toggle. Pure ES5,
// fully defensive (a throw can never break the doc). It flips the EN / 中文 blocks
// inside every bilingual panel and remembers the choice per-device. During highlight
// mode it snaps back to English-first, because the doc's sentence-pairing
// (collectPairs) assumes that order; the user's preference is restored on exit.
const LANG_TOGGLE_JS = `(function(){
  try {
    var btn = document.getElementById('langToggle');
    if (!btn) return;
    var KEY = 'prepdoc_langfirst';
    function getFirst(){ try { return localStorage.getItem(KEY) === 'zh' ? 'zh' : 'en'; } catch(e){ return 'en'; } }
    function headLang(el){
      var h = el.tagName === 'H3' ? el : (el.querySelector ? el.querySelector('h3') : null);
      if (!h) return null;
      if (/English/i.test(h.textContent)) return 'en';
      if (/中文/.test(h.textContent)) return 'zh';
      return null;
    }
    function orderBody(pb, first){
      var kids = Array.prototype.slice.call(pb.children), ei = -1, zi = -1, i, l;
      for (i = 0; i < kids.length; i++){ l = headLang(kids[i]); if (l === 'en' && ei < 0) ei = i; if (l === 'zh' && zi < 0) zi = i; }
      if (ei < 0 || zi < 0) return;
      if (((ei < zi) ? 'en' : 'zh') === first) return;
      var lo = Math.min(ei, zi), hi = Math.max(ei, zi), middle = kids.slice(lo, hi), divider = null;
      for (i = 0; i < middle.length; i++){ if (middle[i].classList && middle[i].classList.contains('divider')){ divider = middle[i]; break; } }
      var firstBlock = middle.filter(function(el){ return el !== divider; });
      kids.slice(hi).concat(divider ? [divider] : [], firstBlock).forEach(function(n){ pb.appendChild(n); });
    }
    function applyOrder(first){
      var bodies = document.querySelectorAll('.panel .panel-body'), i;
      for (i = 0; i < bodies.length; i++) orderBody(bodies[i], first);
    }
    function paint(first){
      var tx = btn.querySelector('.lt-tx');
      if (tx) tx.textContent = (first === 'zh') ? '中文在前' : '英文在前';
      btn.setAttribute('aria-pressed', first === 'zh' ? 'true' : 'false');
    }
    function setFirst(first, save){
      applyOrder(first); paint(first);
      if (save){ try { localStorage.setItem(KEY, first); } catch(e){} }
    }
    btn.addEventListener('click', function(){
      if (document.body.classList.contains('highlighting')) return;
      setFirst(getFirst() === 'zh' ? 'en' : 'zh', true);
    });
    try {
      var mo = new MutationObserver(function(){
        if (document.body.classList.contains('highlighting')) applyOrder('en');
        else { applyOrder(getFirst()); paint(getFirst()); }
      });
      mo.observe(document.body, { attributes: true, attributeFilter: ['class'] });
    } catch(e){}
    setFirst(getFirst(), false);
  } catch(e){}
})();`;

// Graft the language-order toggle onto the served HTML at request time. Because it
// runs in the serve path, it applies to BOTH the baked doc AND an online-saved
// override — so it can never disturb saved content (e.g. highlights): the stored
// HTML is served untouched and the toggle is added on top. Idempotent (skips if the
// HTML already has the button) and fail-safe (any unmatched anchor leaves the HTML
// as-is; the whole thing is wrapped in try/catch). The button is anchored to the
// MAIN sidebar title only, not the subnav ones.
function injectLangToggle(html) {
  try {
    if (typeof html !== 'string' || html.indexOf('id="langToggle"') >= 0) return html;
    const button = '\n    <button id="langToggle" type="button" aria-pressed="false" title="切换所有稿子的中英顺序：英文在前 / 中文在前"><span class="lt-ic" aria-hidden="true">⇄</span><span class="lt-tx">英文在前</span></button>';
    html = html.replace(/(<nav class="sidebar">\s*<div class="sidebar-title">[^<]*<\/div>)/, '$1' + button);
    const css = '<style id="langToggleCss">#langToggle{display:inline-flex;align-items:center;gap:6px;margin:4px 8px 10px;padding:6px 11px;font-family:inherit;font-size:12px;font-weight:700;letter-spacing:.2px;color:#bfe3d8;background:#15303a;border:1px solid #2b4a52;border-radius:7px;cursor:pointer;transition:background .12s,color .12s}#langToggle:hover{background:#1f4350;color:#fff}#langToggle .lt-ic{font-size:13px;opacity:.85}.layout.nav-collapsed nav.sidebar #langToggle{display:none}</style>';
    html = html.replace('</head>', css + '\n</head>');
    const js = '<script id="langToggleJs">' + LANG_TOGGLE_JS + '</' + 'script>';
    html = html.replace('</body>', js + '\n</body>');
    return html;
  } catch (e) { return html; }
}

// Panels whose latest published version always wins, even inside a saved-highlight
// override — so editing a self-intro never forces the user to lose their highlights.
const FRESH_PANELS = ['mm-intro'];
function sectionRe(id) {
  // order-independent: match any <section ... id="ID" ...> ... </section>
  return new RegExp('<section [^>]*\\bid="' + id + '"[^>]*>[\\s\\S]*?</section>');
}
function refreshPanels(overrideHtml, baseHtml) {
  let out = overrideHtml;
  for (let i = 0; i < FRESH_PANELS.length; i++) {
    const m = baseHtml.match(sectionRe(FRESH_PANELS[i]));
    if (m) out = out.replace(sectionRe(FRESH_PANELS[i]), function () { return m[0]; });
  }
  return out;
}

module.exports = async (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  if (!auth.configured() || !keyCandidates().length) {
    res.status(503).send('Prep doc not configured — set COPILOT_PASS (and optionally COPILOT_KEY) in Vercel, then redeploy.');
    return;
  }
  if (!auth.isAuthed(req)) {
    if (req.method === 'POST') { res.status(401).json({ ok: false, error: 'locked' }); return; }
    res.status(401).send('Locked — please log in.');
    return;
  }

  // ----- Save an online edit (silent; no file dialog on the client) -----
  if (req.method === 'POST') {
    if (!storeOn()) { res.status(200).json({ ok: false, error: 'no_store' }); return; }
    let body = req.body;
    if (!body || typeof body === 'string') {
      try { body = JSON.parse(body || '{}'); } catch (e) { body = {}; }
    }
    if (body && body.reset) {
      try { await pipe([['DEL', STORE_KEY]]); res.status(200).json({ ok: true, reset: true }); }
      catch (e) { res.status(200).json({ ok: false, error: 'exception' }); }
      return;
    }
    const html = body && body.html;
    if (typeof html !== 'string' || html.length < 200) { res.status(200).json({ ok: false, error: 'bad_html' }); return; }
    const enc = encryptDoc(html);
    if (!enc) { res.status(200).json({ ok: false, error: 'no_key' }); return; }
    const savedAt = Date.now();
    try {
      await pipe([['SET', STORE_KEY, JSON.stringify({ iv: enc.iv, data: enc.data, savedAt: savedAt })]]);
      res.status(200).json({ ok: true, savedAt: savedAt });
    } catch (e) { res.status(200).json({ ok: false, error: 'exception' }); }
    return;
  }

  // ----- Serve the doc: a NEWER online edit wins over the published bake -----
  let html = null, ts = DOC_BUILD;
  try {
    const ov = await loadOverride();
    if (ov && ov.savedAt > DOC_BUILD) {
      html = ov.html; ts = ov.savedAt;
      // Keep the self-intro panel(s) fresh even inside the saved-highlight snapshot,
      // so this edit shows up without wiping the user's other highlights.
      try { html = refreshPanels(html, decryptDoc()); } catch (e) { /* serve override as-is */ }
    }
  } catch (e) { /* fall through to baked */ }
  if (html == null) { try { html = decryptDoc(); } catch (e) { html = null; } }
  if (html == null) { res.status(500).send('Decrypt failed — check COPILOT_KEY.'); return; }
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.status(200).send(injectBuilt(injectLangToggle(html), ts));
};
